for item,line in zip(order,notes):
 e,g=lookup[item['id']];words,sc,subject,comp,gap=line.split('|');size,_,colour=sc.partition(' ')
 with Image.open(O/'extra_thumbs'/f"{e['id']}.jpg") as im:
  rgb=np.asarray(im.convert('RGB'),dtype=float);luma=rgb@np.array([.2126,.7152,.0722]);sat=np.asarray(im.convert('HSV'))[:,:,1]
 title=e['title'];shape='What happens if' if title.lower().startswith(('what if','what happens if')) else 'question' if '?' in title else 'number' if re.search(r'\d',title) else 'statement'
 hook=next((re.search(r'\b'+re.escape(h)+r'\b',title,re.I).group() for h in hooks if re.search(r'\b'+re.escape(h)+r'\b',title,re.I)), '[no vocabulary match]')
 rows.append(dict(id=e['id'],channel=g['channel'],format=g['tab'],title=title,published=e['published'],views=e['views'],age_days=round(e['age_days'],5),views_per_day=round(e['views_per_day'],2),under_one_day=e['under_one_day'],fast_10=e['id'] in g['fast_ids'],slow_10=e['id'] in g['slow_ids'],title_shape=shape,title_chars=len(title),title_hook_vocabulary_tag=hook,thumbnail_words=words,text_size=size,text_colour=colour or 'none',subject_type=subject,composition=comp,curiosity_gap_interpretation=gap,luma_std_whole_rendition=round(float(luma.std()),1),near_black_pct_luma_lt20_whole_rendition=round(float((luma<20).mean()*100),1),mean_saturation_whole_rendition=round(float(sat.mean()),1),source=e['url']))
